-- Reverse of apply.sql, except the 7 deleted placeholder rows (junk; they are in the recovery point's DB backup).
-- Removes the 6 new publishers (with their feeds and articles), puts the APR tag feeds back, re-enables PINA. Generated by Build-Sql.py.
\set ON_ERROR_STOP on
SET lock_timeout = '5s';
BEGIN;
CREATE TEMP TABLE gone ON COMMIT DROP AS
  SELECT s.id AS sub, s.publisher_id AS pub FROM publisher_submissions s WHERE s.verification_detail LIKE '%' || '[added by Claude 2026-10-18, Build #93 Pacific feeds]';
DO $$ DECLARE n int; BEGIN SELECT count(*) INTO n FROM gone; IF n <> 6 THEN RAISE EXCEPTION 'found % tagged submissions, expected 6', n; END IF; END $$;
SELECT 'articles|' || count(*) FROM articles WHERE publisher_id IN (SELECT pub FROM gone);
DELETE FROM articles WHERE publisher_id IN (SELECT pub FROM gone);
DELETE FROM feeds WHERE publisher_id IN (SELECT pub FROM gone);
DELETE FROM editorial_profiles WHERE publisher_id IN (SELECT pub FROM gone);
UPDATE publisher_submissions SET publisher_id = NULL WHERE id IN (SELECT sub FROM gone);
DELETE FROM publishers WHERE id IN (SELECT pub FROM gone);
DELETE FROM publisher_submissions WHERE id IN (SELECT sub FROM gone);
UPDATE feeds SET feed_url = 'https://asiapacificreport.nz/tag/vanuatu/feed/' WHERE publisher_id = 2070 AND feed_url = 'https://asiapacificreport.nz/category/pacific/vanuatu/feed/';
UPDATE feeds SET feed_url = 'https://asiapacificreport.nz/tag/samoa/feed/' WHERE publisher_id = 2072 AND feed_url = 'https://asiapacificreport.nz/category/pacific/samoa/feed/';
UPDATE feeds SET feed_url = 'https://asiapacificreport.nz/tag/micronesia/feed/' WHERE publisher_id = 2076 AND feed_url = 'https://asiapacificreport.nz/category/pacific/federated-states-of-micronesia/feed/';
UPDATE feeds SET enabled = true WHERE publisher_id = ANY(ARRAY[2069,2074,2075,2077,2079,2080,2081]);
UPDATE publishers SET feed_status = 'active' WHERE id = ANY(ARRAY[2069,2074,2075,2077,2079,2080,2081]);
COMMIT;
SELECT 'reversed|' || count(*) || ' tagged submissions left' FROM publisher_submissions WHERE verification_detail LIKE '%' || '[added by Claude 2026-10-18, Build #93 Pacific feeds]';
